// Builds src/words/answers.js and src/words/guesses.js from a SCOWL release.
//
// Usage: node scripts/build-word-lists.mjs <path-to-unpacked-scowl>
//
// SCOWL: http://wordlist.aspell.net/ (release 2020.12.07 was used).
// The lists are only regenerated by hand; the app never runs this script.

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const scowlDir = process.argv[2];
if (!scowlDir || !existsSync(join(scowlDir, 'final'))) {
  console.error('Usage: node scripts/build-word-lists.mjs <path-to-unpacked-scowl>');
  process.exit(1);
}

const LEVELS = [10, 20, 35, 40, 50, 55, 60, 70, 80, 95];
const CATEGORIES = ['english-words', 'american-words', 'british-words'];
const ANSWER_MAX_LEVEL = 35; // common words
const GUESS_MAX_LEVEL = 80; // bigger list, still real words
const TABOO_FILES = ['offensive.1', 'offensive.2', 'profane.1', 'profane.3'];

function readLines(file) {
  // SCOWL files are Latin-1 encoded.
  return readFileSync(file, 'latin1').split(/\r?\n/).filter(Boolean);
}

function wordsUpTo(maxLevel) {
  const words = new Set();
  for (const level of LEVELS.filter((l) => l <= maxLevel)) {
    for (const category of CATEGORIES) {
      const file = join(scowlDir, 'final', `${category}.${level}`);
      if (existsSync(file)) readLines(file).forEach((w) => words.add(w));
    }
  }
  return words;
}

const allWords = wordsUpTo(95);
const taboo = new Set(
  TABOO_FILES.flatMap((f) => readLines(join(scowlDir, 'misc', f))).map((w) => w.toLowerCase()),
);

const isFiveLetters = (w) => /^[a-z]{5}$/.test(w);

// A plural (or third-person verb) is a word ending in s whose stem is also a word.
function isPlural(w) {
  if (!w.endsWith('s') || w.endsWith('ss')) return false;
  if (allWords.has(w.slice(0, -1))) return true;
  if (w.endsWith('es') && allWords.has(w.slice(0, -2))) return true;
  if (w.endsWith('ies') && allWords.has(`${w.slice(0, -3)}y`)) return true;
  return false;
}

// A past tense is a word ending in ed whose stem is a common word (ASKED, BAKED, CRIED, UPPED).
// Real words such as BLEED, BREED and NAKED have no such stem and are kept.
const commonWords = wordsUpTo(70);
function isPastTense(w) {
  if (!w.endsWith('ed')) return false;
  const stems = [w.slice(0, -1), w.slice(0, -2)];
  if (w.endsWith('ied')) stems.push(`${w.slice(0, -3)}y`);
  if (w.at(-3) === w.at(-4)) stems.push(w.slice(0, -3));
  return stems.some((s) => commonWords.has(s));
}

// Irregular plurals, a prefix, and words unsuitable as a puzzle answer.
// They stay valid as guesses.
const EXCLUDED_ANSWERS = new Set([
  'algae', 'cacti', 'fungi', 'geese', 'genii', 'radii', 'teeth', 'uteri', 'women',
  'multi',
  'penis', 'semen', 'vulva', 'horny', 'pussy',
]);

const answers = [...wordsUpTo(ANSWER_MAX_LEVEL)]
  .filter(
    (w) =>
      isFiveLetters(w) && !taboo.has(w) && !isPlural(w) && !isPastTense(w) && !EXCLUDED_ANSWERS.has(w),
  )
  .sort();

const guesses = [...new Set([...wordsUpTo(GUESS_MAX_LEVEL), ...answers])]
  .filter((w) => isFiveLetters(w) && !taboo.has(w))
  .sort();

const NOTICE = `/*! Word list derived from SCOWL (http://wordlist.aspell.net/), release 2020.12.07.
 * Copyright 2000-2016 by Kevin Atkinson. Permission to use, copy, modify,
 * distribute and sell these word lists, the associated scripts, the output
 * created from the scripts, and its documentation for any purpose is hereby
 * granted without fee, provided that the above copyright notice appears in all
 * copies and that both that copyright notice and this permission notice appear
 * in supporting documentation. Kevin Atkinson makes no representations about
 * the suitability of this array for any purpose. It is provided "as is"
 * without express or implied warranty. See src/words/SOURCE.md.
 */`;

function writeList(file, name, words) {
  const lines = [];
  for (let i = 0; i < words.length; i += 12) {
    lines.push(words.slice(i, i + 12).join(' ').toUpperCase());
  }
  const body = `${NOTICE}
// Generated by scripts/build-word-lists.mjs. Do not edit by hand.
export const ${name} = \`
${lines.join('\n')}
\`.trim().split(/\\s+/);
`;
  writeFileSync(file, body);
  console.log(`${file}: ${words.length} words`);
}

writeList('src/words/answers.js', 'ANSWERS', answers);
writeList('src/words/guesses.js', 'GUESSES', guesses);
